import Foundation
import QualityGateCore
@testable import DesignTokenDriftAuditor

/// A small generated token file, written out by hand so every expected value in the tests is
/// enumerated here and not computed by the code under test.
enum TokenFixtures {
    static let css = """
    /* Generated by design-tokens. Do not edit. */
    :root {
      --label: #111214;
      --label-rgb: 17, 18, 20;
      --accent: #FF8D28;
      --accent-rgb: 255, 141, 40;
      --destructive: #FF383C;
      --rule-hairline: 1px;
      --gutter: 16px;
      --space-unit: 4px;
      --columns: 12;
      --radius-container: 0;
      --radius-control: 4px;
      --type-label-size: 11px;
      --type-caption-size: 13px;
      --type-body-size: 16px;
      --type-heading-size: 28px;
      --type-title-size: 34px;
      --type-display-size: clamp(64px, 13vw, 168px);
    }
    @media (prefers-color-scheme: dark) {
      :root:not([data-theme="light"]) {
        --accent: #FF9230;
      }
    }
    """

    static var tokens: TokenSet { TokenSet.parse(css: css) }

    /// Rule ids and lines, in order, for compact assertions.
    static func hits(_ diagnostics: [Diagnostic]) -> [String] {
        diagnostics.map { "\($0.ruleId ?? "nil"):\($0.lineNumber ?? -1)" }
    }
}

/// A throwaway project directory for whole-run tests.
struct DriftProject {
    let root: URL

    init(files: [String: String]) throws {
        root = FileManager.default.temporaryDirectory.appendingPathComponent("drift-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        for (relative, text) in files {
            let url = root.appendingPathComponent(relative)
            try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try text.write(to: url, atomically: true, encoding: .utf8)
        }
    }

    func remove() { try? FileManager.default.removeItem(at: root) } // silent: temp-dir cleanup in a test

    func configuration(_ designTokens: DesignTokensConfig) -> Configuration {
        var configuration = Configuration()
        configuration.projectRoot = root
        configuration.designTokens = designTokens
        return configuration
    }
}
